    void next(std::string h){finish();header=lower(h);if(header=="global"){global.clear();master.clear();group.clear();}else if(header=="master"){master.clear();group.clear();}else if(header=="group")group.clear();else if(header!="region"&&header!="control")report.warn("header <"+header+">");}
